/**
 * The OceanMind agent's compilation pipeline. Everything the learner sees is
 * generated by the connected LLM, grounded in the topic resources — and lessons
 * are composed from a catalog of LIVE INTERACTIVE BLOCKS, not plain text.
 */
import { aiJson, aiChat } from '../ai.js';
import { topChunks } from './retrieval.js';
import { ZONES } from '../content/topics.js';

const SYSTEM = `You are OceanMind, an AI teaching agent. You design learning experiences about AI topics.
You ALWAYS ground your content in the provided SOURCE MATERIAL — never contradict it, prefer its terminology and examples.
You teach through INTERACTION first: visuals, animations, and hands-on blocks carry the explanation; text only guides what to do and notice.
You reply with ONLY valid JSON, no prose around it.`;

/* ------------------------------------------------ interactive block catalog */

const AUTHORABLE = `
- {"type":"diagram","nodes":[{"id","label","detail"}],"edges":[{"from","to","label"}]} — animated clickable flow diagram YOU author. USE for any architecture/process.
- {"type":"chart","kind":"line"|"bar","title","xLabel","yLabel","series":[{"name","points":[[x,y]]}]} — animated chart YOU author with real illustrative numbers. USE for trends (loss curves, overfitting, rates).
- {"type":"simulator","title","expr":"<formula>","xVar":"x","xRange":[min,max],"vars":[{"name","min","max","init","step"}],"yLabel"} — a LIVE MINI-APP you author: sliders for each var, the curve of expr over xVar redraws live. Allowed in expr: numbers, var names, + - * / ^ ( ), sin cos tan exp log sqrt abs tanh sigmoid relu max min sign, pi, e. Omit xVar to show a single computed value instead of a curve. USE for ANY formula/function the learner should feel: objective functions, activations, learning-rate effects, decay, scores. Example: {"type":"simulator","title":"Objective function","expr":"(y - (w*x + b))^2","xVar":"x","xRange":[-3,3],"vars":[{"name":"w","min":-2,"max":2,"init":1,"step":0.1},{"name":"b","min":-2,"max":2,"init":0,"step":0.1},{"name":"y","min":-2,"max":2,"init":1,"step":0.1}],"yLabel":"squared error"}
- {"type":"sequence","stages":[{"label","detail"}]} — animated stage-by-stage walkthrough YOU author (2-8 stages, auto-play + click). USE for any multi-phase process you need to explain step by step.
- {"type":"check","question":{"text","options":["",""],"correctIndex","explanation"}} — quick self-check.`;

const BLOCKS = {
  'neural-networks': `
- {"type":"bio-neuron"} — clickable biological neuron (dendrites/soma/axon/synapse) animated firing, each part mapped to its maths counterpart. USE for biological neurons and the biology→maths analogy.
- {"type":"neuron"} — interactive neuron anatomy: sliders for inputs/weights/bias, live weighted-sum, animated signal flow. USE for what a neuron computes.
- {"type":"perceptron"} — the perceptron learning rule LIVE: separable 2-D points, one-update-at-a-time, watch the boundary line move until convergence. USE for perceptron/linear separability.
- {"type":"logic-gate"} — a perceptron learning AND/OR/NAND/XOR with truth table + live boundary; XOR visibly fails (not linearly separable). USE for logical gates, linear separability, or motivating hidden layers.
- {"type":"activation"} — live activation-function explorer: sigmoid/tanh/relu curves, draggable input marker. USE for activations & saturation.
- {"type":"forwardpass"} — animated feed-forward walkthrough of a real 2-3-1 network with visible numbers, phase by phase. USE for how data flows through layers.
- {"type":"backprop"} — animated BACKWARD pass on the same network: loss, output delta, hidden deltas, weight update, real numbers at every phase. USE for backpropagation/credit assignment.
- {"type":"loss-explorer"} — live comparison of MSE / MAE / cross-entropy curves as the learner drags a prediction, with a target toggle. USE for objective/cost/loss function TYPES.
- {"type":"gradient"} — gradient-descent lab: click a 1-D loss curve to drop a ball, tune learning rate, local minima. USE for basic training/loss/learning-rate.
- {"type":"loss-surface-3d"} — a real 3-D loss landscape the learner can ORBIT with the mouse, shaded by height, with a ball descending it and leaving a trail. USE for loss surfaces, gradients/Hessian, or whenever a wow-factor 3-D view of optimization helps.
- {"type":"gd-variants"} — batch vs mini-batch vs stochastic gradient descent racing across a contour map, showing smooth vs noisy paths. USE for gradient-descent VARIANTS.
- {"type":"optimizer-race"} — SGD vs Momentum racing on a bumpy loss curve, tunable η and β. USE for momentum/optimizers escaping local minima.
- {"type":"vanishing-gradient"} — bar chart of gradient magnitude per layer as depth grows, switchable sigmoid/tanh/ReLU, dead layers marked. USE for vanishing gradients and why ReLU won.
- {"type":"chain-rule"} — interactive computational graph (x·w → +b → σ) that lights up hop by hop as the chain rule multiplies local derivatives. USE for the chain rule / backprop maths.
- {"type":"nn-playground"} — full trainable network on 2-D data: place points, train live, watch the decision boundary. USE as the main hands-on build.${AUTHORABLE}`,
  'ai-agents': `
- {"type":"agent-loop"} — animated think→act→observe→done cycle, clickable stages. USE for the core loop.
- {"type":"pattern-explorer","initial":"augmented-llm"|"chaining"|"routing"|"parallel"|"orchestrator"|"evaluator"|"agent"} — ALL architecture patterns from the source as interactive animated diagrams with when-to-use and tradeoffs. USE for any architecture-pattern teaching; set "initial" to the most relevant pattern.
- {"type":"flow-builder","template":"starter"|"research"|"marketing","goalHint":"optional prefilled test input"} — Zapier-style drag-drop agent builder: the learner wires trigger/LLM/tool/output steps, RUNS them for real, saves and downloads. USE as the main hands-on build; pick the template fitting the learner's goal.
- {"type":"live-agent"} — a real agent the learner configures (goal + tools) and watches think/act/observe live with actual tool execution. USE to show autonomy.
- {"type":"memory"} — context-window simulator: switch between keep-everything / sliding window / summarisation and watch the conversation break as the budget shrinks. USE for memory & context management.
- {"type":"guardrails"} — toggle step budgets, tool allow-lists, human approval, spend caps and observability, then run an agent that goes rogue and watch which rail stops it. USE for risks, safety, guardrails, human-in-the-loop.
- {"type":"multi-agent"} — animated centralized (orchestrator) vs decentralized (peer-to-peer) topologies with message pulses and tradeoffs. USE for multi-agent systems.
- {"type":"workflow-vs-agent"} — a short interactive decision tree that tells the learner whether their own task needs an agent, a fixed workflow, or a workflow with a human in the loop. USE for "when should you build an agent".${AUTHORABLE}`,
  chatbots: `
- {"type":"chatbot-builder"} — the learner authors intents (patterns→replies), chats with their rule-based bot, side-by-side with an LLM bot. USE as the main hands-on build.${AUTHORABLE}`,
};

const AUTHORABLE_TYPES = ['diagram', 'chart', 'simulator', 'sequence', 'check'];
const NN_BLOCKS = ['bio-neuron', 'neuron', 'perceptron', 'logic-gate', 'activation', 'forwardpass', 'backprop', 'chain-rule',
  'loss-explorer', 'gradient', 'loss-surface-3d', 'gd-variants', 'optimizer-race', 'vanishing-gradient', 'nn-playground'];
const AGENT_BLOCKS = ['agent-loop', 'pattern-explorer', 'flow-builder', 'live-agent', 'memory', 'guardrails', 'multi-agent', 'workflow-vs-agent'];
const BLOCK_TYPES = {
  'neural-networks': [...NN_BLOCKS, ...AUTHORABLE_TYPES],
  'ai-agents': [...AGENT_BLOCKS, ...AUTHORABLE_TYPES],
  chatbots: ['chatbot-builder', ...AUTHORABLE_TYPES],
};
/** Blocks that take no authored parameters — everything else is validated explicitly. */
export const ALL_BLOCK_TYPES = { ...BLOCK_TYPES };

const SIM_EXPR_RE = /^[\w\s+\-*/^(),.]+$/;
const SIM_FUNCS = new Set(['sin', 'cos', 'tan', 'exp', 'log', 'sqrt', 'abs', 'tanh', 'sigmoid', 'relu', 'max', 'min', 'sign']);
/** Reject expressions that call anything outside the math whitelist (e.g. process.exit). */
function exprIsSafe(expr) {
  if (!SIM_EXPR_RE.test(expr) || expr.length > 300) return false;
  // any identifier immediately followed by "(" must be an allowed function
  const calls = expr.match(/([A-Za-z_]\w*)\s*\(/g) ?? [];
  return calls.every((c) => SIM_FUNCS.has(c.replace(/\s*\($/, '')));
}

/**
 * Try hard to repair a block instead of rejecting it (models get chart/diagram
 * details wrong often). Returns the sanitized block, or null if the block is
 * unfixable and should be dropped from the step.
 */
export function sanitizeBlock(block, topicId) {
  if (!block || typeof block !== 'object') return null;
  if (!BLOCK_TYPES[topicId].includes(block.type)) return null;

  if (block.type === 'check') {
    const q = block.question;
    if (!q || typeof q.text !== 'string' || !Array.isArray(q.options)) return null;
    const options = q.options.filter((o) => typeof o === 'string' && o).slice(0, 4);
    if (options.length < 3) return null;
    let correctIndex = Number(q.correctIndex);
    if (!Number.isInteger(correctIndex) || correctIndex < 0 || correctIndex >= options.length) {
      // if the original correct option survived filtering, find it; else drop
      const orig = q.options?.[q.correctIndex];
      correctIndex = options.indexOf(orig);
      if (correctIndex === -1) return null;
    }
    return { type: 'check', question: { text: q.text, options, correctIndex, explanation: String(q.explanation ?? '') } };
  }

  if (block.type === 'diagram') {
    if (!Array.isArray(block.nodes)) return null;
    const nodes = block.nodes
      .filter((n) => n && (typeof n.id === 'string' || typeof n.id === 'number') && typeof n.label === 'string')
      .map((n) => ({ id: String(n.id), label: n.label, detail: typeof n.detail === 'string' ? n.detail : undefined }))
      .slice(0, 9);
    const seen = new Set();
    const unique = nodes.filter((n) => (seen.has(n.id) ? false : seen.add(n.id)));
    if (unique.length < 2) return null;
    const ids = new Set(unique.map((n) => n.id));
    const edges = (Array.isArray(block.edges) ? block.edges : [])
      .map((e) => ({ from: String(e?.from), to: String(e?.to), label: typeof e?.label === 'string' ? e.label : undefined }))
      .filter((e) => ids.has(e.from) && ids.has(e.to))
      .slice(0, 20);
    return { type: 'diagram', nodes: unique, edges };
  }

  if (block.type === 'chart') {
    const kind = ['line', 'bar'].includes(block.kind) ? block.kind : 'line';
    const rawSeries = Array.isArray(block.series) ? block.series : Array.isArray(block.points) ? [{ name: block.title ?? 'series', points: block.points }] : [];
    const series = rawSeries
      .map((s) => ({
        name: String(s?.name ?? 'series'),
        points: (Array.isArray(s?.points) ? s.points : [])
          .map((p) => (Array.isArray(p) ? [Number(p[0]), Number(p[1])] : p && typeof p === 'object' ? [Number(p.x), Number(p.y)] : null))
          .filter((p) => p && p.every(Number.isFinite))
          .slice(0, 40),
      }))
      .filter((s) => s.points.length >= 2)
      .slice(0, 4);
    if (series.length < 1) return null;
    return {
      type: 'chart', kind, series,
      title: typeof block.title === 'string' ? block.title : undefined,
      xLabel: typeof block.xLabel === 'string' ? block.xLabel : undefined,
      yLabel: typeof block.yLabel === 'string' ? block.yLabel : undefined,
    };
  }

  if (block.type === 'flow-builder') {
    return {
      type: 'flow-builder',
      template: ['starter', 'research', 'marketing'].includes(block.template) ? block.template : 'starter',
      goalHint: typeof block.goalHint === 'string' ? block.goalHint.slice(0, 200) : undefined,
    };
  }

  if (block.type === 'simulator') {
    if (typeof block.expr !== 'string' || !exprIsSafe(block.expr)) return null;
    const vars = (Array.isArray(block.vars) ? block.vars : [])
      .filter((v) => v && /^[A-Za-z_]\w{0,11}$/.test(String(v.name ?? '')))
      .map((v) => {
        const min = Number(v.min), max = Number(v.max);
        if (!Number.isFinite(min) || !Number.isFinite(max) || min >= max) return null;
        const init = Number.isFinite(Number(v.init)) ? Math.min(max, Math.max(min, Number(v.init))) : (min + max) / 2;
        const step = Number.isFinite(Number(v.step)) && Number(v.step) > 0 ? Number(v.step) : (max - min) / 100;
        return { name: String(v.name), min, max, init, step };
      })
      .filter(Boolean)
      .slice(0, 4);
    let xRange;
    if (Array.isArray(block.xRange) && block.xRange.length === 2) {
      const [a, b] = block.xRange.map(Number);
      if (Number.isFinite(a) && Number.isFinite(b) && a < b) xRange = [a, b];
    }
    return {
      type: 'simulator',
      expr: block.expr.trim(),
      title: typeof block.title === 'string' ? block.title.slice(0, 120) : undefined,
      xVar: typeof block.xVar === 'string' && /^[A-Za-z_]\w{0,11}$/.test(block.xVar) ? block.xVar : undefined,
      xRange: xRange ?? [-5, 5],
      vars,
      yLabel: typeof block.yLabel === 'string' ? block.yLabel.slice(0, 40) : undefined,
    };
  }

  if (block.type === 'sequence') {
    const stages = (Array.isArray(block.stages) ? block.stages : [])
      .filter((s) => s && typeof s.label === 'string' && s.label)
      .map((s) => ({ label: s.label.slice(0, 60), detail: String(s.detail ?? '').slice(0, 400) }))
      .slice(0, 8);
    if (stages.length < 2) return null;
    return { type: 'sequence', stages };
  }

  if (block.type === 'pattern-explorer') {
    const valid = ['augmented-llm', 'chaining', 'routing', 'parallel', 'orchestrator', 'evaluator', 'agent'];
    return { type: 'pattern-explorer', initial: valid.includes(block.initial) ? block.initial : 'chaining' };
  }

  // parameterless blocks (neuron, activation, gradient, forwardpass, agent-loop, nn-playground, live-agent, chatbot-builder)
  return { type: block.type };
}

/**
 * Sanitize + validate a step list IN PLACE (repairs what it can, drops what it
 * can't). Only returns an error when the result is genuinely unusable — a
 * mostly-good lesson never fails over one malformed chart.
 */
export function validateSteps(steps, topicId, { min = 4, max = 10, minInteractive = null } = {}) {
  if (!Array.isArray(steps) || steps.length < min || steps.length > max) return `steps must have ${min}-${max} items`;
  let interactive = 0;
  for (const s of steps) {
    if (typeof s?.title !== 'string' || !s.title) return 'each step needs a title';
    if (typeof s?.body !== 'string' || !s.body) return 'each step needs a body';
    if (s.body.length > 900) s.body = `${s.body.slice(0, 880)}…`;
    if (s.block !== undefined) {
      const fixed = sanitizeBlock(s.block, topicId);
      if (fixed) s.block = fixed;
      else delete s.block; // unfixable block → the step survives as guidance text
    }
    if (s.block && s.block.type !== 'check') interactive++;
  }
  const needed = minInteractive ?? Math.max(1, Math.floor(steps.length / 3));
  if (interactive < needed) return `too few working interactive blocks (${interactive}) — include at least ${Math.ceil(steps.length / 2)} valid ones from the catalog`;
  return null;
}

/* ------------------------------------------------ knowledge map */

export async function compileKnowledgeMap(topic) {
  const sources = topChunks(topic.id, `${topic.title} fundamentals core concepts prerequisites`, 6000);
  const validate = (j) => {
    if (!Array.isArray(j?.mustKnow) || j.mustKnow.length < 3 || j.mustKnow.length > 6) return 'mustKnow must have 3-6 items';
    if (!Array.isArray(j?.needToKnow) || j.needToKnow.length < 2 || j.needToKnow.length > 6) return 'needToKnow must have 2-6 items';
    for (const c of [...j.mustKnow, ...j.needToKnow]) {
      if (typeof c?.name !== 'string' || typeof c?.desc !== 'string' || !c.name || !c.desc) return 'each concept needs name and desc strings';
      if (c.desc.length > 160) return 'concept desc must stay under 160 characters';
    }
    return null;
  };
  return aiJson(
    SYSTEM,
    `TASK: knowledge_map
Analyze the topic "${topic.title}" and compile its knowledge map from the source material.

SOURCE MATERIAL:
${sources}

Return JSON: {"mustKnow":[{"name","desc"},...], "needToKnow":[{"name","desc"},...]}
- mustKnow: 4 core prerequisites without which the topic cannot be understood.
- needToKnow: 3-4 supporting concepts that deepen understanding.
- desc: ONE short sentence (max ~20 words), plain language.`,
    validate
  );
}

/* ------------------------------------------------ assessment questions */

function shuffleQuestionOptions(q) {
  const idx = q.options.map((_, i) => i);
  for (let i = idx.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [idx[i], idx[j]] = [idx[j], idx[i]];
  }
  return { ...q, options: idx.map((i) => q.options[i]), correctIndex: idx.indexOf(q.correctIndex) };
}

export async function generateQuestions(topic, knowledgeMap) {
  const concepts = [...knowledgeMap.mustKnow, ...knowledgeMap.needToKnow].map((c) => c.name);
  const sources = topChunks(topic.id, concepts.join(' '), 6000);
  const validate = (j) => {
    if (!Array.isArray(j) || j.length !== 6) return 'must be an array of exactly 6 questions';
    for (const q of j) {
      if (typeof q?.text !== 'string' || !q.text) return 'each question needs text';
      if (q.text.length > 120) return 'question text too long — max 120 characters, keep it brief';
      if (typeof q?.concept !== 'string') return 'each question needs a concept';
      if (!Array.isArray(q?.options) || q.options.length !== 4) return 'each question needs exactly 4 options';
      if (q.options.some((o) => typeof o !== 'string' || o.length > 70)) return 'options must be strings under 70 characters';
      if (!Number.isInteger(q?.correctIndex) || q.correctIndex < 0 || q.correctIndex > 3) return 'correctIndex must be 0-3';
      if (typeof q?.explanation !== 'string' || !q.explanation) return 'each question needs an explanation';
    }
    return null;
  };
  const raw = await aiJson(
    SYSTEM,
    `TASK: questions
Write a placement assessment for "${topic.title}" based on this knowledge map and source material.

KNOWLEDGE MAP CONCEPTS: ${concepts.join(' · ')}

SOURCE MATERIAL:
${sources}

Return JSON: an array of EXACTLY 6 multiple-choice questions:
[{"text","concept","options":["","","",""],"correctIndex":0-3,"explanation"},...]
Rules:
- BREVITY IS CRITICAL: question text max 15 words; each option max 8 words. No scenario paragraphs.
- Each question tests ONE concept from the map; cover 6 different concepts, mustKnow first.
- Difficulty ramps: 1-2 easy, 3-4 medium, 5-6 hard.
- Distractors are plausible misconceptions.
- "explanation": 1-2 short sentences on WHY the correct answer is right.`,
    validate,
    { maxTokens: 4000 }
  );
  return raw.map((q, i) => ({ id: `q${i + 1}`, ...shuffleQuestionOptions(q) }));
}

/* ------------------------------------------------ personalized lesson */

function shuffleChecks(steps) {
  return steps.map((s) =>
    s.block?.type === 'check' ? { ...s, block: { ...s.block, question: shuffleQuestionOptions(s.block.question) } } : s
  );
}

function learnerProfile({ zone, scorePct, answered, supportNote, previousFeedback, userGoal }) {
  const z = ZONES[zone];
  const gaps = (answered ?? []).filter((a) => !a.correct)
    .map((a) => `${a.concept}${a.noIdea ? ' (said "no idea")' : ''}`);
  const known = (answered ?? []).filter((a) => a.correct).map((a) => a.concept);
  return `- Placement: ${z.label} (${z.levelLabel}), scored ${scorePct ?? '—'}% on the placement quiz.
- Concepts they got RIGHT: ${known.length ? known.join(' · ') : 'none'}
- Concepts they MISSED (teach these carefully): ${gaps.length ? gaps.join(' · ') : 'none — go deeper than basics'}
${supportNote ? `- Support team note: "${supportNote}"` : ''}
${previousFeedback ? `- Their complaint about the previous lesson: ${previousFeedback}` : ''}
${userGoal ? `- THEIR STATED GOAL (the whole lesson must be built around this): "${userGoal}"` : ''}`;
}

const LESSON_RULES = (topic, zone) => `Rules:
- INTERACTION-FIRST: at least half the steps must include an interactive block; use at least 2 different block types. The block IS the explanation — the body only says what to do and what to notice (max ~90 words, use **bold** and "- " bullets).
- RELEVANCE IS MANDATORY: each step's block must directly match THAT step's concept (read each block's "USE for …" note and pick accordingly). Never drop in a block just because it looks impressive. If no fixed block fits, AUTHOR a diagram/chart/simulator/sequence about the exact concept. A mismatched block is a failure.
- Sequence like a dive: hook → concept blocks → hands-on build → check → synthesis.
- For diagram/chart blocks YOU author the content — make it specific and correct, grounded in the source.
- ${ZONES[zone].levelLabel} depth: ${zone === 'sunlight' ? 'zero prior knowledge assumed, build intuition before jargon' : zone === 'twilight' ? 'skip absolute basics, focus on mechanics and why things work' : 'skip fundamentals; focus on edge cases, tradeoffs, failure modes, design decisions'}.
AVAILABLE INTERACTIVE BLOCKS for "${topic.title}" (use ONLY these, exactly this JSON shape):${BLOCKS[topic.id]}`;

export async function generateLesson(topic, profile) {
  const { zone } = profile;
  const query = `${(profile.answered ?? []).filter((a) => !a.correct).map((a) => a.concept).join(' ')} ${profile.userGoal ?? ''} ${topic.title}`;
  const sources = topChunks(topic.id, query, 7000);
  const lesson = await aiJson(
    SYSTEM,
    `TASK: lesson
Build a personalized, interactive walkthrough lesson on "${topic.title}" for ONE specific learner.

LEARNER PROFILE:
${learnerProfile(profile)}

SOURCE MATERIAL (teach from this):
${sources}

Return JSON:
{"title","intro","steps":[{"title","body","block":{...} or omitted}]}
5-8 steps. ${LESSON_RULES(topic, zone)}`,
    (j) => {
      if (typeof j?.title !== 'string' || !j.title) return 'lesson needs a title';
      if (typeof j?.intro !== 'string' || !j.intro) return 'lesson needs an intro';
      return validateSteps(j.steps, topic.id, { min: 4, max: 9 });
    },
    // meta is read only by the demo replay provider (a redesign looks like any goal-built lesson in the prompt)
    { maxTokens: 8000, meta: { redesign: Boolean(profile.redesign) } }
  );
  lesson.steps = shuffleChecks(lesson.steps);
  return lesson;
}

/* ------------------------------------------------ the acting tutor agent */

/**
 * Decides how to react to the learner's message:
 *  - answer: plain grounded reply
 *  - expand: insert new interactive steps clarifying something, right after the current step
 *  - redesign: rebuild the remaining experience around the learner's stated goal
 */
export async function tutorDecide(topic, lesson, stepIndex, messages) {
  const last = messages.at(-1)?.content ?? '';
  const sources = topChunks(topic.id, last, 3500);
  const stepList = (lesson?.steps ?? [])
    .map((s, i) => `${i + 1}. ${s.title}${s.block ? ` [${s.block.type}]` : ''}${i === stepIndex ? '  ← learner is here' : ''}`)
    .join('\n');
  return aiJson(
    `You are Lulu 🐙, OceanMind's dive guide — a warm, sharp teaching AGENT inside a lesson, not a chatbot. You can ACT on the lesson itself. You speak as Lulu, briefly and kindly.
TASK: tutor_decide
Reply with ONLY JSON.`,
    `LESSON: "${lesson?.title}" on ${topic.title}
STEPS (with their interactive blocks):
${stepList}

CONVERSATION (latest last):
${messages.map((m) => `${m.role}: ${m.content}`).join('\n')}

SOURCE MATERIAL:
${sources}

Choose ONE action:
1. {"action":"answer","reply":"<grounded answer, max 100 words>"} — for questions a short answer fully resolves.
2. {"action":"expand","about":"<the EXACT thing to clarify, using the learner's own words>","reply":"<tell them what you're adding, max 40 words>"} — when they want deeper/step-by-step clarification of a specific concept: you will insert new interactive steps right after their current step.
3. {"action":"redesign","goal":"<their goal, restated>","reply":"<tell them you're rebuilding the experience around their goal, max 40 words>"} — when they state a personal goal/project: the remaining lesson gets rebuilt around it.
Prefer expand/redesign whenever they'd serve the learner better than words. In "about", quote the learner's request precisely (e.g. "Objective Function (cont'd)") — never generalize it away.`,
    (j) => {
      if (!['answer', 'expand', 'redesign'].includes(j?.action)) return 'action must be answer|expand|redesign';
      if (typeof j?.reply !== 'string' || !j.reply) return 'needs reply';
      if (j.action === 'expand' && typeof j.about !== 'string') return 'expand needs about';
      if (j.action === 'redesign' && typeof j.goal !== 'string') return 'redesign needs goal';
      return null;
    },
    { maxTokens: 1500 }
  );
}

/**
 * Generate 2-3 NEW interactive steps clarifying `about`, to insert mid-lesson.
 * Knows the whole existing lesson so it never duplicates steps or blocks.
 */
export async function generateExpansionSteps(topic, zone, about, lesson, stepIndex, { goal = null } = {}) {
  const sources = topChunks(topic.id, `${about} ${topic.title}`, 6000);
  const currentStep = lesson?.steps?.[stepIndex];
  const existing = (lesson?.steps ?? [])
    .map((s, i) => `${i + 1}. "${s.title}"${s.block ? ` — already uses block: ${s.block.type}` : ''}`)
    .join('\n');
  const usedBlocks = [...new Set((lesson?.steps ?? []).map((s) => s.block?.type).filter(Boolean))];

  const result = await aiJson(
    SYSTEM,
    `TASK: expand_steps
The learner is on step "${currentStep?.title ?? '—'}" and asked for a deeper, step-by-step clarification of EXACTLY this: "${about}".
Create 2-3 NEW steps teaching precisely that, to be inserted right after their current step.

THE LESSON ALREADY CONTAINS (do NOT duplicate any of these titles, do NOT re-teach their content):
${existing}

INTERACTIVE BLOCKS ALREADY USED (do NOT reuse these types unless with clearly different authored content — prefer the authorable blocks: simulator, sequence, diagram, chart, which you can fill with NEW content specific to "${about}"):
${usedBlocks.join(', ') || 'none'}

SOURCE MATERIAL on the requested concept:
${sources}

Return JSON: {"steps":[{"title","body","block":{...} or omitted}]}
Rules for these steps specifically:
- Laser-focused on "${about}" — the titles should visibly reference it.
- Each step MUST include an interactive block; the "simulator" block lets you build a live mini-app for any formula (perfect for objective functions, update rules, scores), "sequence" for any multi-phase process.
- Body max ~90 words: what to do in the block and what to notice.
${LESSON_RULES(topic, zone)}`,
    (j) => validateSteps(j?.steps, topic.id, { min: 1, max: 3, minInteractive: 1 }),
    // meta is read only by the demo replay provider
    { maxTokens: 6000, meta: { goal } }
  );
  return shuffleChecks(result.steps);
}

/* ------------------------------------------------ dive-log summary */

/** Personal post-lesson summary: what THIS learner learned, did, and should do next. */
export async function generateSummary(topic, { zone, scorePct, answered, lesson, goal }) {
  const stepList = (lesson?.steps ?? [])
    .map((s) => `- ${s.title}${s.block ? ` [interactive: ${s.block.type}]` : ''}`)
    .join('\n');
  const gaps = (answered ?? []).filter((a) => !a.correct).map((a) => a.concept);
  const validate = (j) => {
    if (typeof j?.headline !== 'string' || !j.headline || j.headline.length > 120) return 'needs a headline under 120 chars';
    for (const k of ['learned', 'built', 'nextSteps']) {
      if (!Array.isArray(j?.[k]) || j[k].length < 2 || j[k].length > 5) return `${k} needs 2-5 items`;
      if (j[k].some((x) => typeof x !== 'string' || !x || x.length > 140)) return `${k} items must be short strings (max 140 chars)`;
    }
    return null;
  };
  return aiJson(
    SYSTEM,
    `TASK: summary
The learner just finished this personalized lesson on "${topic.title}" (${ZONES[zone].label}, placement ${scorePct ?? '—'}%).

LESSON STEPS THEY COMPLETED:
${stepList}

CONCEPTS THEY ORIGINALLY MISSED IN THE PLACEMENT QUIZ: ${gaps.length ? gaps.join(' · ') : 'none'}
${goal ? `THEIR GOAL (in their own words — connect the log to it where it fits): "${goal}"\n` : ''}
Write their dive log. Return JSON:
{"headline":"one warm sentence about what they achieved","learned":["…"],"built":["…"],"nextSteps":["…"]}
- learned: 3-5 concrete concepts they now understand (address their original gaps explicitly where covered).
- built: 2-4 things they actually did/made in the interactive blocks (trained, wired, tested…).
- nextSteps: 2-3 specific suggestions to go deeper.
- Every item ONE short sentence, spoken directly to them ("You …").`,
    validate,
    { maxTokens: 2500 }
  );
}

/* ------------------------------------------------ free-text topic match */

export async function aiTopicMatch(text, topics) {
  const ids = topics.map((t) => t.id);
  const answer = await aiChat(
    `You classify a learning request into exactly one of: ${ids.join(', ')}, or "none". Reply with only that single token.\nTASK: topic_match`,
    [{ role: 'user', content: text }],
    { maxTokens: 800 }
  );
  const cleaned = answer.trim().toLowerCase().replace(/[^a-z-]/g, '');
  return ids.includes(cleaned) ? cleaned : null;
}
